using Microsoft.EntityFrameworkCore;

public sealed class OrderSummaries(ShopDb db)
{
    public async Task<List<OrderSummary>> ListAsync(
        DateTime since, CancellationToken ct)
    {
        // One query instead of 111, but whole entities from five tables
        var orders = await db.Orders
            .Include(o => o.Customer)
            .Include(o => o.Lines).ThenInclude(l => l.Product)
            .Include(o => o.Payments)
            .Where(o => o.PlacedAt >= since)
            .ToListAsync(ct); // tested: 1,500 rows, 17 columns, 730 tracked
        return orders.Select(o => new OrderSummary(o.Id, o.Customer.Name,
            o.Lines.Sum(l => l.Quantity * l.UnitPrice), o.Payments.Count)).ToList();
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class OrderSummaries(ShopDb db)
{
    public Task<List<OrderSummary>> ListAsync(
        DateTime since, CancellationToken ct) =>
        db.Orders
            .Where(o => o.PlacedAt >= since)
            // Sum and Count run in SQL: one row per order, four columns
            .Select(o => new OrderSummary(
                o.Id,
                o.Customer.Name,
                o.Lines.Sum(l => l.Quantity * l.UnitPrice),
                o.Payments.Count))
            .ToListAsync(ct); // tested: 50 rows, nothing tracked
}

