using Microsoft.EntityFrameworkCore;

public sealed class OrderDetailsQuery(ShopDb db)
{
    public Task<OrderDetails> GetAsync(int id, CancellationToken ct) =>
        db.Orders.Where(o => o.Id == id)
            .Select(o => new OrderDetails(o.Id, o.Customer.Name,
                o.Lines.Select(l => new LineDto(l.Product.Name, l.Quantity))
                    .ToList(),
                o.Payments.Select(p => new PaymentDto(p.Amount, p.PaidAt))
                    .ToList()))
            // One SQL query per collection instead of lines × payments rows
            .AsSplitQuery()
            .SingleAsync(ct);
}
